using System.Text.Json;

namespace Fleet.Orchestrator.Services;

/// <summary>
/// Supplied by the independently authorized immutable preparation selection, never generated by
/// the artifact adapter. An approval reference is not an approval issuer or an enabled authority.
/// </summary>
public sealed record OpenShellResourceAdmission(string ApprovalReference, string PolicyAcknowledgement, string LabelsJson)
{
    public IReadOnlyDictionary<string, string> Validate(string workspace, string? qualifiedCurrentPolicy = null)
    {
        if (string.IsNullOrWhiteSpace(ApprovalReference) || ApprovalReference.Length > 128 || ApprovalReference.Any(char.IsControl)
            || workspace.Length is < 1 or > 63 || !Value(workspace) || LabelsJson.Length > 16384)
            throw Blocked();
        var required = Required(PolicyAcknowledgement);
        if (qualifiedCurrentPolicy is not null && !required.SequenceEqual(Required(qualifiedCurrentPolicy))) throw Blocked();
        using var json = JsonDocument.Parse(LabelsJson);
        if (json.RootElement.ValueKind != JsonValueKind.Object) throw Blocked();
        var labels = new SortedDictionary<string, string>(StringComparer.Ordinal);
        foreach (var property in json.RootElement.EnumerateObject())
        {
            if (!Key(property.Name) || Reserved(property.Name) || property.Value.ValueKind != JsonValueKind.String
                || !Value(property.Value.GetString()!) || !labels.TryAdd(property.Name, property.Value.GetString()!)) throw Blocked();
        }
        foreach (var (key, expected) in required)
            if (!labels.TryGetValue(key, out var actual) || actual != (expected == "${workspace}" ? workspace : expected)) throw Blocked();
        return labels;
    }
    private static SortedDictionary<string, string> Required(string acknowledgement)
    {
        if (acknowledgement.Length > 16384 || !acknowledgement.StartsWith("v1:", StringComparison.Ordinal)) throw Blocked();
        using var json = JsonDocument.Parse(acknowledgement[3..]);
        var root = json.RootElement;
        Fields(root, "allow_driver_config", "resource_admission");
        if (root.GetProperty("allow_driver_config").ValueKind != JsonValueKind.True) throw Blocked();
        var policy = root.GetProperty("resource_admission"); Fields(policy, "enabled", "required_labels");
        if (policy.GetProperty("enabled").ValueKind != JsonValueKind.True) throw Blocked();
        var source = policy.GetProperty("required_labels");
        if (source.ValueKind != JsonValueKind.Object) throw Blocked();
        var required = new SortedDictionary<string, string>(StringComparer.Ordinal);
        foreach (var property in source.EnumerateObject())
        {
            if (!Key(property.Name) || Reserved(property.Name) || property.Value.ValueKind != JsonValueKind.String) throw Blocked();
            var value = property.Value.GetString()!;
            if (value != "${workspace}" && !Value(value) || !required.TryAdd(property.Name, value)) throw Blocked();
        }
        // Bootstrap volumes must be scoped, even if another custom policy permits shared resources.
        if (required.Count == 0 || !required.ContainsValue("${workspace}")) throw Blocked();
        return required;
    }
    private static void Fields(JsonElement value, params string[] expected)
    {
        if (value.ValueKind != JsonValueKind.Object) throw Blocked();
        var fields = value.EnumerateObject().Select(p => p.Name).ToArray();
        if (fields.Length != expected.Length || fields.Distinct(StringComparer.Ordinal).Count() != expected.Length
            || fields.Any(f => !expected.Contains(f, StringComparer.Ordinal))) throw Blocked();
    }
    // Exact pinned label grammar, including the optional lowercase DNS prefix.
    private static bool Key(string value)
    {
        var slash = value.IndexOf('/');
        var name = slash < 0 ? value : value[(slash + 1)..];
        if (name.Length == 0 || !Value(name)) return false;
        if (slash < 0) return true;
        var prefix = value[..slash];
        return prefix.Length is > 0 and <= 253 && prefix.Split('.').All(part => part.Length is > 0 and <= 63
            && char.IsAsciiLetterOrDigit(part[0]) && char.IsAsciiLetterOrDigit(part[^1])
            && part.All(c => char.IsAsciiLetterLower(c) || char.IsAsciiDigit(c) || c == '-'));
    }
    private static bool Value(string? value) => value is not null && value.Length <= 63 && (value.Length == 0
        || char.IsAsciiLetterOrDigit(value[0]) && char.IsAsciiLetterOrDigit(value[^1])
            && value.All(c => char.IsAsciiLetterOrDigit(c) || c is '-' or '_' or '.'));
    private static bool Reserved(string key) => key is "bootstrap-owner" or "openshell.ai/managed-by" or "openshell.ai/gateway-id"
        or "openshell.ai/sandbox-workspace" or "openshell.ai/caller-driver-config-used" or "openshell.ai/resource-admission-identities";
    private static OpenShellStateConflictException Blocked() => new("bootstrap_resource_admission_unqualified");
}
